1	package govflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"reflect"
13		"sort"
14		"strconv"
15		"strings"
16		"sync"
17		"syscall"
18	)
19	
20	// 资金库状态文件相关错误。
21	var (
22		// ErrTreasuryAlreadyInit：初始化目标路径已存在文件，新文件才能初始化。
23		ErrTreasuryAlreadyInit = errors.New("treasury init refused: state file already exists")
24		// ErrStateCorrupt：状态文件损坏或不是受支持的资金库状态文件。
25		ErrStateCorrupt = errors.New("treasury state file is corrupt")
26		// ErrProposalNotFound：按编号查询或执行时提案不存在。
27		ErrProposalNotFound = errors.New("proposal not found")
28		// ErrProposalConflict：同编号提案再次登记但时间锁或动作原文与首次不同。
29		ErrProposalConflict = errors.New("proposal already registered with different timelock or actions")
30		// ErrInvalidRegistration：登记参数非法（编号为空、初始余额越界等）。
31		ErrInvalidRegistration = errors.New("invalid registration")
32	)
33	
34	const (
35		stateMagic   = "govflow-treasury-state"
36		stateVersion = 1
37		lockSuffix   = ".lock"
38	)
39	
40	// BalanceUpdate 记录一个账户在一次动作前后的余额。
41	type BalanceUpdate struct {
42		Account string `json:"account"`
43		Before  int64  `json:"before"`
44		After   int64  `json:"after"`
45	}
46	
47	// ActionReceipt 是凭据中对单项动作的留痕：动作原文、在提案中的顺序编号（0 起），
48	// 以及该动作引发的资金库与收款账户余额变动。
49	type ActionReceipt struct {
50		Index     int           `json:"index"`
51		Action    string        `json:"action"`
52		Treasury  BalanceUpdate `json:"treasury"`
53		Recipient BalanceUpdate `json:"recipient"`
54	}
55	
56	// Receipt 是一项提案首次成功执行后生成的执行凭据。
57	// 一项提案只允许成功一次；重试返回同一份凭据。
58	//
59	// executed_at 必须明确写出且不得早于对应提案的 timelock_end：首次执行只在
60	// now 达到时间锁后发生，保存的凭据必须满足同一条执行资格规则。字段缺失、
61	// 为 null 或类型不符都不得被折叠成 0 再当作合法凭据读出，因此解码时保留
62	// 字段的原始 JSON，由 validateState 区分“缺失/空值/类型不符/早于时间锁”。
63	type Receipt struct {
64		ProposalID string          `json:"proposal_id"`
65		ExecutedAt int64           `json:"executed_at"` // 首次成功执行时调用方提供的时间
66		Order      int             `json:"order"`       // 成功提交的先后顺序，0 起
67		Actions    []ActionReceipt `json:"actions"`
68	
69		executedAtRaw json.RawMessage
70	}
71	
72	// receiptJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
73	type receiptJSONShape struct {
74		ProposalID string          `json:"proposal_id"`
75		ExecutedAt json.RawMessage `json:"executed_at"`
76		Order      int             `json:"order"`
77		Actions    []ActionReceipt `json:"actions"`
78	}
79	
80	// UnmarshalJSON 保留 executed_at 是否出现及其原始写法（缺失为 nil、null 为
81	// "null"），使“字段缺失”与“显式写出 0”在解码后仍可区分：encoding/json 直接
82	// 解进 int64 会把缺失/null/类型不符都折叠成 0。判定统一交给 validateState，
83	// 此处只在字段确实是 int64 整数时填充 ExecutedAt。
84	func (r *Receipt) UnmarshalJSON(data []byte) error {
85		var shape receiptJSONShape
86		if err := json.Unmarshal(data, &shape); err != nil {
87			return err
88		}
89		r.ProposalID = shape.ProposalID
90		r.Order = shape.Order
91		r.Actions = shape.Actions
92		r.executedAtRaw = shape.ExecutedAt
93		fillInt64(shape.ExecutedAt, &r.ExecutedAt)
94		return nil
95	}
96	
97	// ProposalRecord 是已登记提案的对外视图。State 只可能是 passed 或 executed。
98	type ProposalRecord struct {
99		ID          string   `json:"id"`
100		State       string   `json:"state"`
101		TimelockEnd int64    `json:"timelock_end"`
102		Actions     []string `json:"actions"`
103	}
104	
105	// ---- 磁盘结构（JSON） ----
106	
107	type storedProposal struct {
108		ID          string   `json:"id"`
109		State       string   `json:"state"`
110		TimelockEnd int64    `json:"timelock_end"`
111		Actions     []string `json:"actions"`
112	}
113	
114	type storedState struct {
115		Magic           string                         `json:"magic"`
116		Version         int                            `json:"version"`
117		InitialTreasury int64                          `json:"initial_treasury"`
118		Treasury        int64                          `json:"treasury"`
119		Balances        map[string]int64               `json:"balances"`
120		Proposals       map[string]*storedProposal     `json:"proposals"`
121		Receipts        []*Receipt                     `json:"receipts"`
122		VoteProposals   map[string]*storedVoteProposal `json:"vote_proposals"`
123	}
124	
125	// Store 是绑定到单个本地状态文件的资金库句柄。
126	// 多个 goroutine 可并发使用同一个 Store；不同 Store/进程操作同一状态文件时，
127	// 通过进程内互斥锁与文件锁（flock）串行化。
128	type Store struct {
129		path   string
130		mu     sync.Mutex // 保护本句柄上的全部操作
131		lockFD *os.File   // 跨进程文件锁
132		closed bool
133	}
134	
135	// 进程内按规范路径共享的互斥锁，保证同进程内多个 Store 句柄也互相串行。
136	var (
137		pathLocksMu sync.Mutex
138		pathLocks   = map[string]*sync.Mutex{}
139	)
140	
141	// canonicalPath 将路径规范化为绝对路径，保证不同拼写（如 t.json 与 ./t.json）
142	// 命中同一把进程内锁与同一个锁文件。有意不解析符号链接：文件在初始化前后必须
143	// 解析到同一个键，硬链接/绑定挂载等更深层别名不在本地单文件场景的处理范围内。
144	func canonicalPath(path string) (string, error) {
145		return filepath.Abs(path)
146	}
147	
148	func inProcessLock(path string) *sync.Mutex {
149		pathLocksMu.Lock()
150		defer pathLocksMu.Unlock()
151		m, ok := pathLocks[path]
152		if !ok {
153			m = &sync.Mutex{}
154			pathLocks[path] = m
155		}
156		return m
157	}
158	
159	// InitTreasury 创建一个全新的状态文件并写入初始资金库余额。
160	// 只有新文件才能初始化：路径已存在（含损坏文件）一律拒绝，不会重置或覆盖。
161	// treasury 必须落在有符号 64 位整数范围内且不得为负。
162	func InitTreasury(path string, treasury int64) (*Store, error) {
163		if treasury < 0 {
164			return nil, fmt.Errorf("%w: initial treasury balance must not be negative", ErrInvalidRegistration)
165		}
166		path, err := canonicalPath(path)
167		if err != nil {
168			return nil, err
169		}
170		pathMu := inProcessLock(path)
171		pathMu.Lock()
172		defer pathMu.Unlock()
173	
174		// 先打开/创建锁文件并取跨进程锁，再创建状态文件，消除“空文件已出现、
175		// 尚未写入”期间被其它进程 Open 判为损坏的窗口。
176		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
177		if err != nil {
178			return nil, err
179		}
180		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
181			_ = lockFD.Close()
182			return nil, err
183		}
184		// O_EXCL 保证与并发初始化竞争时只有一方成功。
185		fd, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
186		if err != nil {
187			_ = syscall.Flock(int(lockFD.Fd()), syscall.LOCK_UN)
188			_ = lockFD.Close()
189			if errors.Is(err, fs.ErrExist) {
190				return nil, fmt.Errorf("%w: %s", ErrTreasuryAlreadyInit, path)
191			}
192			return nil, err
193		}
194		_ = fd.Close()
195	
196		store := &Store{path: path, lockFD: lockFD}
197		if err := store.commitLocked(newStoredState(treasury)); err != nil {
198			_ = store.funlock()
199			_ = lockFD.Close()
200			_ = os.Remove(path)
201			return nil, err
202		}
203		// 初始化完成后立即释放跨进程锁；后续每次操作各自短持锁。
204		if err := store.funlock(); err != nil {
205			_ = lockFD.Close()
206			_ = os.Remove(path)
207			return nil, err
208		}
209		return store, nil
210	}
211	
212	// Open 打开已有的资金库状态文件。文件损坏时明确拒绝，不会重建或覆盖原文件。
213	func Open(path string) (*Store, error) {
214		path, err := canonicalPath(path)
215		if err != nil {
216			return nil, err
217		}
218		pathMu := inProcessLock(path)
219		pathMu.Lock()
220		defer pathMu.Unlock()
221		return openStoreHoldingPathLock(path)
222	}
223	
224	// openStoreHoldingPathLock 的调用方必须持有该路径的进程内互斥锁。
225	func openStoreHoldingPathLock(path string) (*Store, error) {
226		if _, err := os.Stat(path); err != nil {
227			return nil, err
228		}
229		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
230		if err != nil {
231			return nil, err
232		}
233		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
234			_ = lockFD.Close()
235			return nil, err
236		}
237		store := &Store{path: path, lockFD: lockFD}
238		if _, err := store.loadLocked(); err != nil {
239			_ = store.funlock()
240			_ = lockFD.Close()
241			return nil, err
242		}
243		// 打开时已做严格校验；锁随即释放，每次操作再各自短持锁。
244		if err := store.funlock(); err != nil {
245			_ = lockFD.Close()
246			return nil, err
247		}
248		return store, nil
249	}
250	
251	// Path 返回状态文件路径。
252	func (s *Store) Path() string { return s.path }
253	
254	// Close 释放文件锁。关闭后其它操作返回错误。
255	func (s *Store) Close() error {
256		s.mu.Lock()
257		defer s.mu.Unlock()
258		if s.closed {
259			return nil
260		}
261		s.closed = true
262		if err := s.funlock(); err != nil {
263			_ = s.lockFD.Close()
264			return err
265		}
266		return s.lockFD.Close()
267	}
268	
269	func (s *Store) flock(how int) error {
270		if s.lockFD == nil {
271			return errors.New("treasury store is closed")
272		}
273		return syscall.Flock(int(s.lockFD.Fd()), how)
274	}
275	
276	func (s *Store) funlock() error {
277		if s.lockFD == nil {
278			return nil
279		}
280		return syscall.Flock(int(s.lockFD.Fd()), syscall.LOCK_UN)
281	}
282	
283	// begin 串行化一次读改写操作：先取进程内路径锁，再取跨进程排他文件锁。
284	// 返回的 commit 在操作结束时释放锁。
285	func (s *Store) begin() (func(), error) {
286		pathMu := inProcessLock(s.path)
287		pathMu.Lock()
288		s.mu.Lock()
289		if s.closed {
290			s.mu.Unlock()
291			pathMu.Unlock()
292			return nil, errors.New("treasury store is closed")
293		}
294		if err := s.flock(syscall.LOCK_EX); err != nil {
295			s.mu.Unlock()
296			pathMu.Unlock()
297			return nil, err
298		}
299		return func() {
300			_ = s.funlock()
301			s.mu.Unlock()
302			pathMu.Unlock()
303		}, nil
304	}
305	
306	func newStoredState(treasury int64) *storedState {
307		return &storedState{
308			Magic:           stateMagic,
309			Version:         stateVersion,
310			InitialTreasury: treasury,
311			Treasury:        treasury,
312			Balances:        map[string]int64{},
313			Proposals:       map[string]*storedProposal{},
314			Receipts:        []*Receipt{},
315			VoteProposals:   map[string]*storedVoteProposal{},
316		}
317	}
318	
319	// ---- 登记 ----
320	
321	// Register 登记一项已通过（passed）的提案，保留时间锁与动作原文。
322	// 编号必须非空；动作列表可为空（执行时会因动作为空被拒绝），动作原文不做改写。
323	// 同编号且时间锁、动作原文与首次登记完全相同的重试返回 existed=true；
324	// 内容不同则返回 ErrProposalConflict。
325	func (s *Store) Register(id string, timelockEnd int64, actions []string) (existed bool, err error) {
326		if id == "" {
327			return false, fmt.Errorf("%w: proposal id must not be empty", ErrInvalidRegistration)
328		}
329		commit, err := s.begin()
330		if err != nil {
331			return false, err
332		}
333		defer commit()
334	
335		state, err := s.loadLocked()
336		if err != nil {
337			return false, err
338		}
339		stored := copyActions(actions)
340		if existing, ok := state.Proposals[id]; ok {
341			if existing.TimelockEnd == timelockEnd && sameActions(existing.Actions, stored) {
342				return true, nil
343			}
344			return false, fmt.Errorf("%w: proposal %s", ErrProposalConflict, id)
345		}
346		// 两种来源共用编号：register 不能覆盖投票提案或绕过其投票结论。
347		if vp, ok := state.VoteProposals[id]; ok {
348			return false, fmt.Errorf("%w: proposal id %s belongs to a voting proposal (state=%s)", ErrProposalConflict, id, vp.State)
349		}
350		state.Proposals[id] = &storedProposal{
351			ID:          id,
352			State:       "passed",
353			TimelockEnd: timelockEnd,
354			Actions:     stored,
355		}
356		if err := s.commitLocked(state); err != nil {
357			return false, err
358		}
359		return false, nil
360	}
361	
362	func copyActions(actions []string) []string {
363		if actions == nil {
364			return nil
365		}
366		copied := make([]string, len(actions))
367		copy(copied, actions)
368		return copied
369	}
370	
371	// sameActions 将 nil 与空切片视为等价，其余按顺序逐字比较。
372	func sameActions(a, b []string) bool {
373		if len(a) != len(b) {
374			return false
375		}
376		for i := range a {
377			if a[i] != b[i] {
378				return false
379			}
380		}
381		return true
382	}
383	
384	// ---- 执行 ----
385	
386	// executionTarget 是 register 与投票两种来源提案在执行路径上的统一视图。
387	type executionTarget struct {
388		state        string
389		timelockEnd  int64
390		actions      []string
391		markExecuted func()
392	}
393	
394	// resolveExecutable 在两种提案表中按编号定位执行目标；不存在返回 nil。
395	func resolveExecutable(state *storedState, id string) *executionTarget {
396		if p, ok := state.Proposals[id]; ok {
397			return &executionTarget{
398				state:        p.State,
399				timelockEnd:  p.TimelockEnd,
400				actions:      p.Actions,
401				markExecuted: func() { p.State = "executed" },
402			}
403		}
404		if vp, ok := state.VoteProposals[id]; ok {
405			return &executionTarget{
406				state:        vp.State,
407				timelockEnd:  vp.TimelockEnd,
408				actions:      vp.Actions,
409				markExecuted: func() { vp.State = "executed" },
410			}
411		}
412		return nil
413	}
