672	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
673	func (s *Store) loadLocked() (*storedState, error) {
674		raw, err := os.ReadFile(s.path)
675		if err != nil {
676			return nil, err
677		}
678		if len(bytes.TrimSpace(raw)) == 0 {
679			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
680		}
681		if err := checkStateStructure(raw); err != nil {
682			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
683		}
684		var state storedState
685		dec := json.NewDecoder(bytes.NewReader(raw))
686		dec.DisallowUnknownFields()
687		if err := dec.Decode(&state); err != nil {
688			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
689		}
690		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
691		var extra json.RawMessage
692		if err := dec.Decode(&extra); err != io.EOF {
693			if err == nil {
694				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
695			}
696			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
697		}
698		if err := validateState(&state); err != nil {
699			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
700		}
701		return &state, nil
702	}
703	
704	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
705	// 任一步失败都保留上次完整状态。调用方必须持锁。
706	func (s *Store) commitLocked(state *storedState) error {
707		if err := validateState(state); err != nil {
708			return fmt.Errorf("refusing to persist invalid state: %w", err)
709		}
710		payload, err := json.MarshalIndent(state, "", "  ")
711		if err != nil {
712			return err
713		}
714		payload = append(payload, '\n')
715	
716		dir := filepath.Dir(s.path)
717		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
718		if err != nil {
719			return err
720		}
721		tmpName := tmp.Name()
722		cleanup := func() { _ = os.Remove(tmpName) }
723		if _, err := tmp.Write(payload); err != nil {
724			_ = tmp.Close()
725			cleanup()
726			return err
727		}
728		if err := tmp.Sync(); err != nil {
729			_ = tmp.Close()
730			cleanup()
731			return err
732		}
733		if err := tmp.Close(); err != nil {
734			cleanup()
735			return err
736		}
737		if err := os.Chmod(tmpName, 0o600); err != nil {
738			cleanup()
739			return err
740		}
741		if err := os.Rename(tmpName, s.path); err != nil {
742			cleanup()
743			return err
744		}
745		if err := syncDir(dir); err != nil {
746			return err
747		}
748		return nil
749	}
750	
751	func syncDir(dir string) error {
752		d, err := os.Open(dir)
753		if err != nil {
754			return err
755		}
756		defer d.Close()
757		return d.Sync()
758	}
759	
760	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
761	func validateState(state *storedState) error {
762		if state.Magic != stateMagic {
763			return fmt.Errorf("bad magic %q", state.Magic)
764		}
765		if state.Version != stateVersion {
766			return fmt.Errorf("unsupported state version %d", state.Version)
767		}
768		if state.InitialTreasury < 0 {
769			return errors.New("initial treasury balance is negative")
770		}
771		if state.Treasury < 0 {
772			return errors.New("treasury balance is negative")
773		}
774		if state.Balances == nil {
775			return errors.New("balances table is missing")
776		}
777		if state.Proposals == nil {
778			return errors.New("proposals table is missing")
779		}
780		if state.Receipts == nil {
781			return errors.New("receipts table is missing")
782		}
783		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
784		if state.VoteProposals == nil {
785			state.VoteProposals = map[string]*storedVoteProposal{}
786		}
787		for account, balance := range state.Balances {
788			if account == "" {
789				return errors.New("balance entry with empty account")
790			}
791			if balance < 0 {
792				return fmt.Errorf("balance of %q is negative", account)
793			}
794		}
795		for key, p := range state.Proposals {
796			if p == nil {
797				return fmt.Errorf("proposal %q is empty", key)
798			}
799			if p.ID != key || p.ID == "" {
800				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
801			}
802			if p.State != "passed" && p.State != "executed" {
803				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
804			}
805			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
806		}
807		if err := validateVoteProposals(state); err != nil {
808			return err
809		}
810	
811		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
812		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
813		simTreasury := state.InitialTreasury
814		simBalances := map[string]int64{}
815		seenReceipts := map[string]int{}
816		for order, rcpt := range state.Receipts {
817			if rcpt == nil {
818				return fmt.Errorf("receipt %d is empty", order)
819			}
820			if rcpt.Order != order {
821				return fmt.Errorf("receipt %q order field is %d, expected %d", rcpt.ProposalID, rcpt.Order, order)
822			}
823			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
824				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
825			}
826			seenReceipts[rcpt.ProposalID] = order
827			ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
828			if !found {
829				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
830			}
831			if ownerState != "executed" {
832				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
833			}
834			// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
835			// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
836			if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
837				return err
838			}
839			// 凭据声明的逐笔转账由统一转账规则（verifyReceiptTransfers）重放
840			// 核对：动作条数/编号/原文、资金库与收款账户前后余额任一不符都带
841			// 动作位置报损坏原因；本函数随即返回错误，整份状态被拒绝，重放结果
842			// 不会被查询或落盘采纳。
843			var verr error
844			simTreasury, verr = verifyReceiptTransfers(rcpt, ownerActions, simTreasury, simBalances)
845			if verr != nil {
846				return verr
847			}
848		}
849		if simTreasury != state.Treasury {
850			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
851		}
852		if len(simBalances) != len(state.Balances) {
853			return fmt.Errorf("balance table has %d accounts, receipt replay yields %d", len(state.Balances), len(simBalances))
854		}
855		for account, balance := range state.Balances {
856			if simBalances[account] != balance {
857				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
858			}
859		}
860		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
861		for _, p := range state.Proposals {
862			_, hasReceipt := seenReceipts[p.ID]
863			if p.State == "executed" && !hasReceipt {
864				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
865			}
866		}
867		for _, p := range state.VoteProposals {
868			_, hasReceipt := seenReceipts[p.ID]
869			if p.State == "executed" && !hasReceipt {
870				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
871			}
872		}
873		return nil
874	}
875	
876	// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
877	// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
878	// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
879	// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
880	// 位置（0 起），与提案编号一起用于定位。
881	// “缺失/空值/类型不符”的判定与逐票明细、计票结果共用同一份规则
882	// （requiredScalarProblem），此处只补充凭据的业务位置与执行资格检查。
883	func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
884		if problem := requiredScalarProblem(rcpt.executedAtRaw, scalarInteger); problem != "" {
885			return fmt.Errorf("receipt %d for proposal %q field %q %s", order, rcpt.ProposalID, "executed_at", problem)
886		}
887		if rcpt.ExecutedAt < timelockEnd {
888			return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
889				order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
890		}
891		return nil
892	}
893	
894	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
895	
896	// schemaKind 是状态文件 JSON 在某一层的形状类别。
897	type schemaKind int
898	
899	const (
900		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
901		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
902		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
903		kindArray                     // 数组
904		kindString                    // 叶子：必须是 JSON 字符串
905		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
906		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
907	)
908	
909	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
910	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
911	type schemaNode struct {
912		kind   schemaKind
913		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
914		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
915	}
916	
917	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
918	func schemaOf(t reflect.Type) *schemaNode {
919		for t.Kind() == reflect.Pointer {
920			t = t.Elem()
921		}
922		switch t.Kind() {
923		case reflect.Struct:
924			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
925			for i := 0; i < t.NumField(); i++ {
926				f := t.Field(i)
927				if f.PkgPath != "" { // 未导出字段不参与 JSON
928					continue
929				}
930				name := f.Name
931				if tag, ok := f.Tag.Lookup("json"); ok {
932					tagName, _, _ := strings.Cut(tag, ",")
933					if tagName == "-" {
934						continue
935					}
936					if tagName != "" {
937						name = tagName
938					}
939				}
940				node.fields[name] = schemaOf(f.Type)
941			}
942			return node
943		case reflect.Map:
944			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
945		case reflect.Slice, reflect.Array:
946			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
947		case reflect.String:
948			return &schemaNode{kind: kindString}
949		case reflect.Bool:
950			return &schemaNode{kind: kindBoolean}
951		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
952			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
953			return &schemaNode{kind: kindInteger}
954		default:
955			return &schemaNode{kind: kindAny}
956		}
957	}
958	
959	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
960	
961	func init() {
962		// 票据的四个标量字段（representative/weight/support/voted_at）由
963		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
964		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
965		// 不抢在解码器之前用不含票据定位的通用信息报错。
966		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
967		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
968			ballotFields[name].kind = kindAny
969		}
970		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
971		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
972		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
973		// 其“不早于截止”的既有校验不变。
974		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
975		for _, name := range []string{"for_weight", "against_weight"} {
976			tallyFields[name].kind = kindAny
977		}
978		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
979		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
980		// 叶子位置保持宽松。
981		storedStateSchema.fields["receipts"].elem.fields["executed_at"].kind = kindAny
982	}
983	
984	// scanFrame 是结构扫描的栈帧。
985	type scanFrame struct {
986		node    *schemaNode
987		isArray bool
988		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
989		seen    map[string]bool
990		atValue bool // 对象帧：下一个待消费 token 是值而非键
991		index   int  // 数组帧：下一个元素下标
992		path    string
993	}
994	
995	func peekFrame(stack []*scanFrame) *scanFrame {
996		if len(stack) == 0 {
997			return nil
998		}
999		return stack[len(stack)-1]
1000	}
1001	
1002	// checkStateStructure 在解码前逐 token 扫描状态文件：
1003	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1004	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1005	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1006	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1007	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1008	//
1009	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1010	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1011	func checkStateStructure(raw []byte) error {
1012		dec := json.NewDecoder(bytes.NewReader(raw))
1013		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1014		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1015		dec.UseNumber()
1016		var stack []*scanFrame
1017		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1018		pendingNode := storedStateSchema
1019		pendingPath := "state"
1020	
1021		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1022		finishValue := func() {
1023			top := peekFrame(stack)
1024			if top == nil || top.opaque {
1025				return
1026			}
1027			if top.isArray {
1028				top.index++
1029			} else {
1030				top.atValue = false
1031			}
1032		}
1033	
1034		for {
1035			tok, err := dec.Token()
1036			if err == io.EOF {
1037				if len(stack) != 0 {
1038					return errors.New("unterminated object or array")
1039				}
1040				return nil
1041			}
1042			if err != nil {
1043				return err
1044			}
1045	
1046			if top := peekFrame(stack); top != nil && top.opaque {
1047				// 不透明容器内不做字段检查，只配对括号。
1048				if d, ok := tok.(json.Delim); ok {
1049					if d == '{' || d == '[' {
1050						stack = append(stack, &scanFrame{opaque: true})
1051					} else {
1052						stack = stack[:len(stack)-1]
1053						finishValue()
1054					}
1055				}
1056				continue
1057			}
1058	
1059			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1060				// 对象帧的键位置：闭括号或下一个键。
1061				if d, ok := tok.(json.Delim); ok {
1062					if d != '}' {
1063						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1064					}
1065					stack = stack[:len(stack)-1]
1066					finishValue()
1067					continue
1068				}
1069				key, ok := tok.(string)
1070				if !ok {
1071					return errors.New("object key must be a string")
1072				}
1073				if top.seen[key] {
1074					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1075				}
1076				top.seen[key] = true
1077				top.atValue = true
1078				switch top.node.kind {
1079				case kindObject:
1080					child, known := top.node.fields[key]
1081					if !known {
1082						return fmt.Errorf("unknown field %q at %s", key, top.path)
1083					}
1084					pendingNode = child
1085					pendingPath = top.path + "." + key
1086				case kindMap:
1087					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1088					pendingNode = top.node.elem
1089					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1090				}
1091				continue
1092			}
1093	
1094			// 值位置：对象键之后的值或数组元素。
1095			node := pendingNode
1096			path := pendingPath
1097			if top := peekFrame(stack); top != nil && top.isArray {
1098				node = top.node.elem
1099				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1100			}
1101			if d, ok := tok.(json.Delim); ok {
1102				switch d {
1103				case '{', '[':
1104					frame := &scanFrame{isArray: d == '[', path: path}
1105					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1106						(d == '[' && node.kind == kindArray)
1107					if !shapeOK {
1108						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1109						frame.opaque = true
1110					} else {
1111						frame.node = node
1112						if d == '{' {
1113							frame.seen = map[string]bool{}
1114						}
1115					}
1116					stack = append(stack, frame)
1117				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1118					if len(stack) == 0 {
1119						return errors.New("unexpected closing delimiter")
1120					}
1121					stack = stack[:len(stack)-1]
1122					finishValue()
1123				}
1124				continue
1125			}
1126			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1127			// null 不允许用来顶替字符串/布尔/整数。
1128			if err := checkLeafScalar(node, path, tok); err != nil {
1129				return err
1130			}
1131			finishValue()
1132		}
1133	}
1134	
1135	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1136	func leafKindName(k schemaKind) string {
1137		switch k {
1138		case kindString:
1139			return "string"
1140		case kindBoolean:
1141			return "boolean"
1142		case kindInteger:
1143			return "integer"
1144		default:
1145			return "value"
1146		}
1147	}
1148	
1149	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1150	func tokenKindName(tok json.Token) string {
1151		switch v := tok.(type) {
1152		case nil:
1153			return "null"
1154		case string:
1155			return "string"
1156		case bool:
1157			return "boolean"
1158		case json.Number:
1159			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1160				return "integer"
1161			}
1162			return "number"
1163		default:
1164			return "value"
1165		}
1166	}
1167	
1168	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1169	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1170	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1171		switch node.kind {
1172		case kindString, kindBoolean, kindInteger:
1173		default:
1174			return nil
1175		}
1176		if node.kind == kindInteger {
1177			if n, ok := tok.(json.Number); ok {
1178				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1179					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1180				}
1181				return nil
1182			}
1183		}
1184		want := leafKindName(node.kind)
1185		if got := tokenKindName(tok); got != want {
1186			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1187		}
1188		return nil
1189	}
