393		// 时间锁为 0、在 0 执行的旧凭据：明确写出的 0 是合法执行时间。
394		mustRegister(t, store, "gip-zero", 0, "transfer:z:50")
395		// 登记提案的负时间取值保持兼容。
396		mustRegister(t, store, "gip-neg", -100, "transfer:n:1")
397		if _, err := store.Execute("gip-1", 5001); err != nil {
398			t.Fatal(err)
399		}
400		if _, err := store.Execute("gip-zero", 0); err != nil {
401			t.Fatal(err)
402		}
403		if _, err := store.Execute("gip-neg", -50); err != nil {
404			t.Fatal(err)
405		}
