888	func itoa(i int) string {
889		if i == 0 {
890			return "0"
891		}
892		neg := i < 0
893		if neg {
894			i = -i
895		}
896		var buf [20]byte
897		pos := len(buf)
898		for i > 0 {
899			pos--
900			buf[pos] = byte('0' + i%10)
901			i /= 10
902		}
903		if neg {
904			pos--
905			buf[pos] = '-'
906		}
907		return string(buf[pos:])
908	}
