952					}
953					// rename 之间不应存在损坏窗口；若观察到损坏说明非原子。
954					t.Errorf("observed non-atomic state file: %v", err)
955					return
956				}
957				if _, err := s.TreasuryBalance(); err != nil {
958					t.Errorf("read balance: %v", err)
959				}
960				s.Close()
961			}
962		}()
963		time.Sleep(50 * time.Millisecond)
964		close(stop)
965		wg.Wait()
966	}
967	
968	// TestFixedFieldNamesMustMatchExactly 固定字段名必须与保存格式逐字一致：
969	// 大小写变体（Treasury、Support 等）、同一对象内的大小写双胞胎（state 与 State，
970	// 即使两个值相同）、转义写法的重复键，都导致整个文件被拒绝；
971	// 业务编号（账户、提案编号）的大小写变体是不同编号，不得被合并或拒绝。
972	func TestFixedFieldNamesMustMatchExactly(t *testing.T) {
973		dir := t.TempDir()
974		path := filepath.Join(dir, "treasury.json")
975		store, err := InitTreasury(path, 1000)
976		if err != nil {
977			t.Fatal(err)
978		}
979		// 两个只差大小写的提案编号与收款账户：合法数据，必须都能正常读回。
980		mustRegister(t, store, "GIP-1", 0, "transfer:Audit:100")
981		mustRegister(t, store, "gip-1", 0, "transfer:audit:50")
982		if _, err := store.Execute("GIP-1", 0); err != nil {
983			t.Fatal(err)
984		}
985		if _, err := store.Execute("gip-1", 0); err != nil {
986			t.Fatal(err)
987		}
988		mustCreateVote(t, store, baseVoteInput("gip-vote"))
989		if _, err := store.CastVote("gip-vote", "alice", true, 150); err != nil {
990			t.Fatal(err)
991		}
992		if _, err := store.TallyVote("gip-vote", 200); err != nil {
993			t.Fatal(err)
994		}
995		store.Close()
996	
997		good, err := os.ReadFile(path)
998		if err != nil {
999			t.Fatal(err)
1000		}
1001	
1002		// 正常文件（含大小写不同的业务编号）原样可读。
1003		assertReadable := func(t *testing.T, raw []byte) {
1004			t.Helper()
1005			p := filepath.Join(dir, strings.ReplaceAll(t.Name(), "/", "-")+".json")
1006			if err := os.WriteFile(p, raw, 0o600); err != nil {
1007				t.Fatal(err)
1008			}
1009			s, err := Open(p)
1010			if err != nil {
1011				t.Fatalf("readable variant rejected: %v", err)
1012			}
1013			defer s.Close()
1014			if got, err := s.Balance("Audit"); err != nil || got != 100 {
1015				t.Fatalf("Balance(Audit)=%d err=%v, want 100", got, err)
1016			}
1017			if got, err := s.Balance("audit"); err != nil || got != 50 {
1018				t.Fatalf("Balance(audit)=%d err=%v, want 50", got, err)
1019			}
1020			if _, ok, err := s.Proposal("GIP-1"); err != nil || !ok {
1021				t.Fatalf("Proposal(GIP-1) ok=%v err=%v", ok, err)
1022			}
1023			if _, ok, err := s.Proposal("gip-1"); err != nil || !ok {
1024				t.Fatalf("Proposal(gip-1) ok=%v err=%v", ok, err)
1025			}
1026		}
1027	
1028		t.Run("baseline", func(t *testing.T) { assertReadable(t, good) })
1029	
1030		t.Run("reordered and reindented", func(t *testing.T) {
1031			// 字段顺序与缩进不影响读取。
1032			var asMap map[string]any
1033			if err := json.Unmarshal(good, &asMap); err != nil {
1034				t.Fatal(err)
1035			}
1036			raw, err := json.Marshal(asMap) // map 重marshal后键序变为字典序、无缩进
1037			if err != nil {
1038				t.Fatal(err)
1039			}
1040			assertReadable(t, raw)
1041		})
1042	
1043		t.Run("escaped field names", func(t *testing.T) {
1044			// 转义拼写与普通拼写表示同一个字段：单独出现正常识别。
1045			raw := strings.Replace(string(good), `"version": 1`, `"\u0076ersion": 1`, 1)
1046			raw = strings.Replace(raw, `"timelock_end"`, `"\u0074imelock_end"`, 1)
1047			assertReadable(t, []byte(raw))
1048		})
1049	
1050		// ---- 拒绝变体：每个都整文件拒绝，错误指出字段与所在记录，文件不被改写 ----
1051	
1052		mutate := func(fn func(root map[string]any)) []byte {
1053			var clone map[string]any
1054			if err := json.Unmarshal(good, &clone); err != nil {
1055				t.Fatal(err)
1056			}
1057			fn(clone)
1058			raw, err := json.MarshalIndent(clone, "", "  ")
1059			if err != nil {
1060				t.Fatal(err)
1061			}
1062			return append(raw, '\n')
1063		}
1064		rename := func(obj map[string]any, old, new string) {
1065			v, ok := obj[old]
1066			if !ok {
1067				t.Fatalf("setup: key %q missing", old)
1068			}
1069			obj[new] = v
1070			delete(obj, old)
1071		}
1072		proposal := func(root map[string]any) map[string]any {
1073			return root["proposals"].(map[string]any)["GIP-1"].(map[string]any)
1074		}
1075		vote := func(root map[string]any) map[string]any {
1076			return root["vote_proposals"].(map[string]any)["gip-vote"].(map[string]any)
1077		}
1078		receipt := func(root map[string]any) map[string]any {
1079			return root["receipts"].([]any)[0].(map[string]any)
1080		}
1081	
1082		rejected := map[string]struct {
1083			raw  []byte
1084			want []string // 错误原因应包含的片段（字段名与所在记录）
1085		}{
1086			"top-level Treasury": {
1087				raw:  mutate(func(root map[string]any) { rename(root, "treasury", "Treasury") }),
1088				want: []string{`"Treasury"`},
1089			},
1090			"proposal State": {
1091				raw:  mutate(func(root map[string]any) { rename(proposal(root), "state", "State") }),
1092				want: []string{`"State"`, `proposals["GIP-1"]`},
1093			},
1094			"proposal state and State twins": {
1095				// 同一记录里同时放入 state 与 State，即使值相同也拒绝。
1096				raw: mutate(func(root map[string]any) {
1097					p := proposal(root)
1098					p["State"] = p["state"]
1099				}),
1100				want: []string{`"State"`, `proposals["GIP-1"]`},
1101			},
1102			"ballot Support": {
1103				raw: mutate(func(root map[string]any) {
1104					rename(vote(root)["ballots"].([]any)[0].(map[string]any), "support", "Support")
1105				}),
1106				want: []string{`"Support"`, `vote_proposals["gip-vote"].ballots[0]`},
1107			},
1108			"tally Tallied_at": {
1109				raw: mutate(func(root map[string]any) {
1110					rename(vote(root)["tally"].(map[string]any), "tallied_at", "Tallied_at")
1111				}),
1112				want: []string{`"Tallied_at"`, ".tally"},
1113			},
1114			"receipt Proposal_ID": {
1115				raw:  mutate(func(root map[string]any) { rename(receipt(root), "proposal_id", "Proposal_ID") }),
1116				want: []string{`"Proposal_ID"`, "receipts[0]"},
1117			},
1118			"receipt balance Before": {
1119				raw: mutate(func(root map[string]any) {
1120					rename(receipt(root)["actions"].([]any)[0].(map[string]any)["treasury"].(map[string]any), "before", "Before")
1121				}),
1122				want: []string{`"Before"`, ".treasury"},
1123			},
1124			"member Weight": {
1125				raw: mutate(func(root map[string]any) {
1126					rename(vote(root)["members"].([]any)[0].(map[string]any), "weight", "Weight")
1127				}),
1128				want: []string{`"Weight"`, ".members[0]"},
1129			},
1130			"delegation From": {
1131				raw: mutate(func(root map[string]any) {
1132					rename(vote(root)["delegations"].([]any)[0].(map[string]any), "from", "From")
1133				}),
1134				want: []string{`"From"`, ".delegations[0]"},
1135			},
1136			"unknown field still rejected": {
1137				raw:  mutate(func(root map[string]any) { proposal(root)["comment"] = "x" }),
1138				want: []string{`"comment"`, `proposals["GIP-1"]`},
1139			},
1140			"escaped duplicate state": {
1141				// 转义拼写与普通拼写是同一个键：同一对象出现两次属重复键。
1142				raw: []byte(strings.Replace(string(good),
1143					`"state": "executed"`, `"state": "executed", "st\u0061te": "executed"`, 1)),
1144				want: []string{`duplicate key "state"`, `proposals["GIP-1"]`},
1145			},
1146		}
1147		for name, tc := range rejected {
1148			t.Run(name, func(t *testing.T) {
1149				bad := filepath.Join(dir, "bad-"+strings.ReplaceAll(name, " ", "-")+".json")
1150				if err := os.WriteFile(bad, tc.raw, 0o600); err != nil {
1151					t.Fatal(err)
1152				}
1153				s, err := Open(bad)
1154				if !errors.Is(err, ErrStateCorrupt) {
1155					if s != nil {
1156						s.Close()
1157					}
1158					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
1159				}
1160				for _, want := range tc.want {
1161					if !strings.Contains(err.Error(), want) {
1162						t.Fatalf("error %q should mention %s", err.Error(), want)
1163					}
1164				}
1165				// 损坏文件不被整理或写回。
1166				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
1167					t.Fatalf("corrupt file was modified")
1168				}
1169			})
1170		}
1171	
1172		t.Run("reads after corruption", func(t *testing.T) {
1173			// 打开后文件被改成非法字段：后续读取同样返回状态损坏，不提供部分信息。
1174			p := filepath.Join(dir, "live.json")
1175			if err := os.WriteFile(p, good, 0o600); err != nil {
1176				t.Fatal(err)
1177			}
1178			s, err := Open(p)
1179			if err != nil {
1180				t.Fatal(err)
1181			}
1182			defer s.Close()
1183			bad := mutate(func(root map[string]any) { rename(root, "treasury", "Treasury") })
1184			if err := os.WriteFile(p, bad, 0o600); err != nil {
1185				t.Fatal(err)
1186			}
1187			if _, err := s.BalanceSnapshot(); !errors.Is(err, ErrStateCorrupt) {
1188				t.Fatalf("BalanceSnapshot on corrupted file err=%v, want ErrStateCorrupt", err)
1189			}
1190			if _, _, err := s.Proposal("GIP-1"); !errors.Is(err, ErrStateCorrupt) {
1191				t.Fatalf("Proposal on corrupted file err=%v, want ErrStateCorrupt", err)
1192			}
1193		})
1194	}
