281		}
282	
283		store, err := govflow.Open(cf.state)
284		if err != nil {
285			fail(err)
286		}
287		defer store.Close()
288		in := &govflow.CreateVoteInput{
289			ID:          *id,
290			Members:     []govflow.VoteMember(members),
291			Delegations: []govflow.Delegation(delegations),
292			Quorum:      quorum,
293			StartAt:     start,
294			Deadline:    deadline,
295			TimelockEnd: timelock,
296			Actions:     []string(actions),
297		}
298		view, existed, err := store.CreateVoteProposal(in)
299		if err != nil {
300			fail(err)
301		}
302		if cf.asJSON {
303			emitJSON(map[string]any{"proposal": view, "already_exists": existed})
304			return
305		}
306		if existed {
307			fmt.Printf("voting proposal %s already exists with identical content (state=%s)\n", view.ID, view.State)
308		} else {
309			fmt.Printf("created voting proposal %s: %d member(s), total_weight=%d, quorum=%d, voting=[%d,%d), timelock_end=%d, %d action(s)\n",
310				view.ID, len(view.Members), view.TotalWeight, view.Quorum, view.StartAt, view.Deadline, view.TimelockEnd, len(view.Actions))
311		}
312	}
