1	package govflow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"math"
7		"os"
8		"path/filepath"
9		"reflect"
10		"strings"
11		"testing"
12	)
13	
14	// TestPlanTransfersChainsBalances：统一转账规则按动作原顺序扣款/加款，
15	// 未出现过的收款账户从零开始，同一账户连续收款时后一笔承接前一笔结果，
16	// 金额恰好等于资金库剩余余额时扣款到 0 仍成功。
17	func TestPlanTransfersChainsBalances(t *testing.T) {
18		steps, treasury, balances, err := planTransfers(
19			[]string{"transfer:audits:250", "transfer:audits:100", "transfer:legal:50"},
20			1000, nil)
21		if err != nil {
22			t.Fatalf("planTransfers: %v", err)
23		}
24		want := []struct {
25			acct           string
26			tb, ta, rb, ra int64
27		}{
28			{"audits", 1000, 750, 0, 250},
29			{"audits", 750, 650, 250, 350}, // 同一账户连续收款
30			{"legal", 650, 600, 0, 50},
31		}
32		for i, w := range want {
33			st := steps[i]
34			if st.account != w.acct || st.treasuryBefore != w.tb || st.treasuryAfter != w.ta ||
35				st.recipientBefore != w.rb || st.recipientAfter != w.ra || st.failure != nil {
36				t.Fatalf("step %d = %+v, want acct=%s treasury=%d->%d recipient=%d->%d",
37					i, st, w.acct, w.tb, w.ta, w.rb, w.ra)
38			}
39			if got := st.actionReceipt(i, "transfer:"+w.acct+":x"); got.Treasury.Account != "treasury" ||
40				got.Recipient.Account != w.acct || got.Index != i {
41				t.Fatalf("actionReceipt shape wrong: %+v", got)
42			}
43		}
44		if treasury != 600 {
45			t.Fatalf("treasury = %d, want 600", treasury)
46		}
47		if balances["audits"] != 350 || balances["legal"] != 50 || len(balances) != 2 {
48			t.Fatalf("balances = %+v, want audits=350 legal=50", balances)
49		}
50	
51		// 起始状态中已有的账户余额被承接，且起始表不被修改。
52		start := map[string]int64{"audits": 7}
53		steps, treasury, balances, err = planTransfers([]string{"transfer:audits:3"}, 10, start)
54		if err != nil {
55			t.Fatalf("planTransfers existing: %v", err)
56		}
57		if steps[0].recipientBefore != 7 || steps[0].recipientAfter != 10 ||
58			treasury != 7 || balances["audits"] != 10 {
59			t.Fatalf("existing balance not carried: %+v %d %+v", steps[0], treasury, balances)
60		}
61		if start["audits"] != 7 {
62			t.Fatalf("planTransfers mutated starting balances: %+v", start)
63		}
64	
65		// 金额恰好等于资金库剩余余额：可以成功，资金库扣到 0。
66		steps, treasury, _, err = planTransfers([]string{"transfer:x:10"}, 10, nil)
67		if err != nil || treasury != 0 || steps[0].treasuryAfter != 0 {
68			t.Fatalf("exact-remaining transfer rejected: %v treasury=%d steps=%+v", err, treasury, steps)
69		}
70	}
71	
72	// TestPlanTransfersFailurePrecedence：动作非法、收款溢出、资金库不足的
73	// 分类、动作位置与先报告顺序沿用首次执行路径的既有行为；同一动作同时
74	// 触发收款溢出与资金库不足时先报告溢出。
75	func TestPlanTransfersFailurePrecedence(t *testing.T) {
76		// 动作格式错误：同时匹配 ErrExecutionRejected 与 ErrInvalidAction。
77		_, _, _, err := planTransfers([]string{"transfer:a:1", "withdraw:b:2"}, 1000, nil)
78		if !errors.Is(err, ErrExecutionRejected) || !errors.Is(err, ErrInvalidAction) {
79			t.Fatalf("malformed err=%v, want both sentinels", err)
80		}
81		if !strings.Contains(err.Error(), `action 1 ("withdraw:b:2")`) {
82			t.Fatalf("malformed error lost position/text: %v", err)
83		}
84	
85		// 收款溢出先于资金库不足：资金库只剩 5、账户已接近 int64 上限，
86		// 一笔 10 同时满足两个条件，必须先报溢出并带动作位置。
87		nearMax := map[string]int64{"a": math.MaxInt64 - 5}
88		_, _, _, err = planTransfers([]string{"transfer:a:10"}, 5, nearMax)
89		if !errors.Is(err, ErrExecutionRejected) || errors.Is(err, ErrInvalidAction) {
90			t.Fatalf("overflow err=%v, want ErrExecutionRejected only", err)
91		}
92		if !strings.Contains(err.Error(), "recipient balance overflow at action 0") ||
93			!strings.Contains(err.Error(), "account=a") {
94			t.Fatalf("overflow error wrong/reordered: %v", err)
95		}
96	
97		// 资金库不足（无溢出）：文案与位置保持不变。
98		_, _, _, err = planTransfers([]string{"transfer:mida:600", "transfer:midb:500"}, 1000, nil)
99		if !errors.Is(err, ErrExecutionRejected) ||
100			!strings.Contains(err.Error(), "insufficient treasury balance at action 1") {
101			t.Fatalf("insufficient err=%v", err)
102		}
103	}
104	
105	// TestVerifyReceiptTransfersAcceptsPlannedAndRejectsTamper：执行预演产出的
106	// 逐笔结果构造的凭据必须被重放核对接受（两条路径同源）；篡改任一方的
107	// 前后余额都按既有原因与动作位置拒绝，且不推进重放状态。
108	func TestVerifyReceiptTransfersAcceptsPlannedAndRejectsTamper(t *testing.T) {
109		actions := []string{"transfer:audits:250", "transfer:audits:100", "transfer:legal:50"}
110		steps, _, _, err := planTransfers(actions, 1000, nil)
111		if err != nil {
112			t.Fatal(err)
113		}
114		good := &Receipt{ProposalID: "gip-1"}
115		for i, st := range steps {
116			good.Actions = append(good.Actions, st.actionReceipt(i, actions[i]))
117		}
118		balances := map[string]int64{}
119		treasury, err := verifyReceiptTransfers(good, actions, 1000, balances)
120		if err != nil {
121			t.Fatalf("planned receipt must verify: %v", err)
122		}
123		if treasury != 600 || balances["audits"] != 350 || balances["legal"] != 50 {
124			t.Fatalf("verify result treasury=%d balances=%+v", treasury, balances)
125		}
126	
127		// 重放路径的字段核对顺序：条数/编号/原文 → 资金库前 → 资金库后
128		// （不足在此）→ 收款前 → 收款后（溢出在此）。
129		cases := []struct {
130			name   string
131			tamper func(*ActionReceipt)
132			want   string
133		}{
134			{"treasury before", func(ar *ActionReceipt) { ar.Treasury.Before = 999 },
135				"action 1 treasury before-balance mismatch"},
136			{"treasury after", func(ar *ActionReceipt) { ar.Treasury.After = 651 },
137				"action 1 treasury after-balance mismatch"},
138			{"recipient before", func(ar *ActionReceipt) { ar.Recipient.Before = 249 },
139				"action 1 recipient before-balance mismatch"},
140			{"recipient after", func(ar *ActionReceipt) { ar.Recipient.After = 351 },
141				"action 1 recipient after-balance mismatch"},
142		}
143		for _, tc := range cases {
144			t.Run(tc.name, func(t *testing.T) {
145				bad := &Receipt{ProposalID: "gip-1"}
146				for i, st := range steps {
147					ar := st.actionReceipt(i, actions[i])
148					if i == 1 {
149						tc.tamper(&ar)
150					}
151					bad.Actions = append(bad.Actions, ar)
152				}
153				fresh := map[string]int64{}
154				start := int64(1000)
155				gotTreasury, err := verifyReceiptTransfers(bad, actions, start, fresh)
156				if err == nil || !strings.Contains(err.Error(), tc.want) {
157					t.Fatalf("tamper %s err=%v, want %q", tc.name, err, tc.want)
158				}
159				// 出错动作（第 1 笔）及其后动作不得应用：第 0 笔已核对的结果
160				// audits=250、资金库 750 保留，第 1 笔的 350 与 legal 的 50 不得出现。
161				if len(fresh) != 1 || fresh["audits"] != 250 {
162					t.Fatalf("failing action advanced replay state: %+v", fresh)
163				}
164				if gotTreasury != 750 {
165					t.Fatalf("treasury advanced past failing action: %d", gotTreasury)
166				}
167			})
168		}
169	
170		// 条数、编号、原文不一致沿用既有原因。
171		if _, err := verifyReceiptTransfers(good, actions[:2], 1000, map[string]int64{}); err == nil ||
172			!strings.Contains(err.Error(), "action count 3 does not match proposal 2") {
173			t.Fatalf("count mismatch err=%v", err)
174		}
175		renumbered := *good
176		renumbered.Actions = append([]ActionReceipt(nil), good.Actions...)
177		renumbered.Actions[2].Index = 9
178		if _, err := verifyReceiptTransfers(&renumbered, actions, 1000, map[string]int64{}); err == nil ||
179			!strings.Contains(err.Error(), `action 2 has index 9`) {
180			t.Fatalf("index mismatch err=%v", err)
181		}
182		differentText := append([]string(nil), actions...)
183		differentText[0] = "transfer:audits:251"
184		if _, err := verifyReceiptTransfers(good, differentText, 1000, map[string]int64{}); err == nil ||
185			!strings.Contains(err.Error(), "text does not match registered action") {
186			t.Fatalf("text mismatch err=%v", err)
187		}
188	
189		// 重放侧先核对资金库：一笔同时“资金不足”且“收款溢出”的动作，
190		// 读取路径先报告资金库一侧（与执行路径先报溢出各自保持不变）。
191		// 凭据把资金库后余额写成重算出的 -5（恰好等于 treasury-amount）：
192		// 若按首个失败原因推断会漏掉资金不足而落到收款侧，独立的不足标志
193		// 必须仍让资金库一侧先报错。
194		conflict := &Receipt{ProposalID: "gip-x", Actions: []ActionReceipt{{
195			Index: 0, Action: "transfer:a:10",
196			Treasury:  BalanceUpdate{Account: "treasury", Before: 5, After: -5},
197			Recipient: BalanceUpdate{Account: "a", Before: math.MaxInt64 - 5, After: math.MaxInt64},
198		}}}
199		_, err = verifyReceiptTransfers(conflict, []string{"transfer:a:10"}, 5, map[string]int64{})
200		if err == nil || !strings.Contains(err.Error(), "action 0 treasury after-balance mismatch") {
201			t.Fatalf("replay precedence err=%v, want treasury-side mismatch first", err)
202		}
203	}
204	
205	// TestExecuteExactRemainingAndOverflowBeforeInsufficient：端到端验证
206	// “恰好等于余额可成功”与“溢出先于不足报告”，失败不留任何资金变动/凭据/状态。
207	func TestExecuteExactRemainingAndOverflowBeforeInsufficient(t *testing.T) {
208		store, _ := openTempStore(t, 10)
209		defer store.Close()
210		mustRegister(t, store, "gip-eq", 0, "transfer:a:10")
211		r, err := store.Execute("gip-eq", 0)
212		if err != nil {
213			t.Fatalf("exact-remaining execute: %v", err)
214		}
215		if r.Actions[0].Treasury.Before != 10 || r.Actions[0].Treasury.After != 0 ||
216			r.Actions[0].Recipient.After != 10 {
217			t.Fatalf("exact-remaining receipt: %+v", r.Actions[0])
218		}
219		if bal, _ := store.TreasuryBalance(); bal != 0 {
220			t.Fatalf("treasury = %d, want 0", bal)
221		}
222		if bal, _ := store.Balance("a"); bal != 10 {
223			t.Fatalf("a = %d, want 10", bal)
224		}
225	
226		// 资金库 MaxInt64：先把某账户打到 MaxInt64-5（资金库剩 5），
227		// 再向同一账户转 10 —— 同时溢出且不足，必须先报溢出。
228		big, path2 := openTempStore(t, math.MaxInt64)
229		defer big.Close()
230		mustRegister(t, big, "gip-near", 0, "transfer:a:9223372036854775802")
231		if _, err := big.Execute("gip-near", 0); err != nil {
232			t.Fatalf("setup execute: %v", err)
233		}
234		mustRegister(t, big, "gip-both", 0, "transfer:a:10")
235		_, err = big.Execute("gip-both", 0)
236		if !errors.Is(err, ErrExecutionRejected) || !strings.Contains(err.Error(), "overflow") {
237			t.Fatalf("both-conditions err=%v, want overflow reported first", err)
238		}
239		if bal, _ := big.TreasuryBalance(); bal != 5 {
240			t.Fatalf("treasury changed after failure: %d", bal)
241		}
242		if bal, _ := big.Balance("a"); bal != math.MaxInt64-5 {
243			t.Fatalf("recipient changed after failure: %d", bal)
244		}
245		if rec, ok, _ := big.Receipt("gip-both"); ok || rec != nil {
246			t.Fatalf("receipt left after failure: %+v", rec)
247		}
248		if p, _, _ := big.Proposal("gip-both"); p.State != "passed" {
249			t.Fatalf("state changed after failure: %s", p.State)
250		}
251		// 重开后仍为完整状态：成功凭据与最终余额一致。
252		big.Close()
253		reopened, err := Open(path2)
254		if err != nil {
255			t.Fatalf("reopen: %v", err)
256		}
257		defer reopened.Close()
258		if bal, _ := reopened.TreasuryBalance(); bal != 5 {
259			t.Fatalf("treasury after reopen = %d", bal)
260		}
261	}
262	
263	// TestTamperedReceiptBalancesRejectWithCause：凭据中资金库/收款账户的
264	// 前后余额被篡改时，整份状态判为损坏，错误沿用既有原因与动作位置，
265	// 原文件保持原样，不改成重算结果后继续提供查询。
266	func TestTamperedReceiptBalancesRejectWithCause(t *testing.T) {
267		dir := t.TempDir()
268		path := filepath.Join(dir, "treasury.json")
269		store, err := InitTreasury(path, 1000)
270		if err != nil {
271			t.Fatal(err)
272		}
273		mustRegister(t, store, "gip-1", 0,
274			"transfer:audits:250", "transfer:audits:100", "transfer:legal:50")
275		if _, err := store.Execute("gip-1", 0); err != nil {
276			t.Fatal(err)
277		}
278		store.Close()
279	
280		good, err := os.ReadFile(path)
281		if err != nil {
282			t.Fatal(err)
283		}
284		mutate := func(fn func(actions []any)) []byte {
285			var doc map[string]any
286			if err := json.Unmarshal(good, &doc); err != nil {
287				t.Fatal(err)
288			}
289			rcpt := doc["receipts"].([]any)[0].(map[string]any)
290			fn(rcpt["actions"].([]any))
291			raw, err := json.MarshalIndent(doc, "", "  ")
292			if err != nil {
293				t.Fatal(err)
294			}
295			return append(raw, '\n')
296		}
297		setField := func(actions []any, i int, side string, field string, value any) {
298			entry := actions[i].(map[string]any)[side].(map[string]any)
299			entry[field] = value
300		}
301		cases := []struct {
302			name string
303			raw  []byte
304			want string
305		}{
306			{"treasury-before", mutate(func(a []any) { setField(a, 1, "treasury", "before", 999) }),
307				"action 1 treasury before-balance mismatch"},
308			{"treasury-after", mutate(func(a []any) { setField(a, 1, "treasury", "after", 651) }),
309				"action 1 treasury after-balance mismatch"},
310			{"recipient-before", mutate(func(a []any) { setField(a, 1, "recipient", "before", 249) }),
311				"action 1 recipient before-balance mismatch"},
312			{"recipient-after", mutate(func(a []any) { setField(a, 1, "recipient", "after", 351) }),
313				"action 1 recipient after-balance mismatch"},
314			{"recipient-account", mutate(func(a []any) { setField(a, 0, "recipient", "account", "other") }),
315				"action 0 recipient before-balance mismatch"},
316			{"treasury-account", mutate(func(a []any) { setField(a, 0, "treasury", "account", "vault") }),
317				"action 0 treasury before-balance mismatch"},
318		}
319		for _, tc := range cases {
320			t.Run(tc.name, func(t *testing.T) {
321				bad := filepath.Join(dir, "tamper-"+tc.name+".json")
322				if err := os.WriteFile(bad, tc.raw, 0o600); err != nil {
323					t.Fatal(err)
324				}
325				s, err := Open(bad)
326				if !errors.Is(err, ErrStateCorrupt) {
327					if s != nil {
328						s.Close()
329					}
330					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
331				}
332				if !strings.Contains(err.Error(), tc.want) {
333					t.Fatalf("error %q missing %q", err.Error(), tc.want)
334				}
335				// 原文件保持原样，不被重算结果覆盖。
336				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
337					t.Fatalf("corrupt file was modified")
338				}
339			})
340		}
341	}
342	
343	// TestRegisteredAndVotedProposalsTransferIdentically：相同动作与起始余额下，
344	// 登记来源与投票通过来源的提案产生相同的资金变动与逐笔凭据，且已执行
345	// 提案再次执行仍返回首次凭据。
346	func TestRegisteredAndVotedProposalsTransferIdentically(t *testing.T) {
347		actions := []string{"transfer:audits:250", "transfer:audits:100", "transfer:legal:50"}
348	
349		registered, _ := openTempStore(t, 1000)
350		defer registered.Close()
351		mustRegister(t, registered, "gip-r", 0, actions...)
352		rr, err := registered.Execute("gip-r", 0)
353		if err != nil {
354			t.Fatal(err)
355		}
356	
357		voted, _ := openTempStore(t, 1000)
358		defer voted.Close()
359		in := baseVoteInput("gip-v")
360		in.Actions = actions
361		in.StartAt, in.Deadline, in.TimelockEnd = 0, 1, 1
362		mustCreateVote(t, voted, in)
363		if _, err := voted.CastVote("gip-v", "alice", true, 0); err != nil {
364			t.Fatal(err)
365		}
366		if _, err := voted.TallyVote("gip-v", 1); err != nil {
367			t.Fatal(err)
368		}
369		vr, err := voted.Execute("gip-v", 1)
370		if err != nil {
371			t.Fatal(err)
372		}
373	
374		if len(rr.Actions) != len(vr.Actions) {
375			t.Fatalf("receipt action counts differ: %d vs %d", len(rr.Actions), len(vr.Actions))
376		}
377		for i := range rr.Actions {
378			// 两个来源的凭据只有动作原文（编号相同）与双方前后余额可比。
379			ra, va := rr.Actions[i], vr.Actions[i]
380			if ra.Action != va.Action || !reflect.DeepEqual(ra.Treasury, va.Treasury) ||
381				!reflect.DeepEqual(ra.Recipient, va.Recipient) || ra.Index != va.Index {
382				t.Fatalf("action %d differs by source:\nregistered=%+v\nvoted=%+v", i, ra, va)
383			}
384		}
385		for _, pair := range []struct {
386			name    string
387			store   *Store
388			receipt *Receipt
389			id      string
390		}{
391			{"registered", registered, rr, "gip-r"},
392			{"voted", voted, vr, "gip-v"},
393		} {
394			if bal, _ := pair.store.TreasuryBalance(); bal != 600 {
395				t.Fatalf("%s treasury=%d, want 600", pair.name, bal)
396			}
397			if bal, _ := pair.store.Balance("audits"); bal != 350 {
398				t.Fatalf("%s audits=%d, want 350", pair.name, bal)
399			}
400			if bal, _ := pair.store.Balance("legal"); bal != 50 {
401				t.Fatalf("%s legal=%d, want 50", pair.name, bal)
402			}
403			// 再次执行返回首次凭据，不产生二次资金变动。
404			again, err := pair.store.Execute(pair.id, 99999)
405			if err != nil {
406				t.Fatalf("%s re-execute: %v", pair.name, err)
407			}
408			if again.Order != pair.receipt.Order || again.ExecutedAt != pair.receipt.ExecutedAt ||
409				!reflect.DeepEqual(again.Actions, pair.receipt.Actions) {
410				t.Fatalf("%s re-execute changed receipt:\nfirst=%+v\nagain=%+v", pair.name, pair.receipt, again)
411			}
412			if bal, _ := pair.store.TreasuryBalance(); bal != 600 {
413				t.Fatalf("%s treasury changed on retry: %d", pair.name, bal)
414			}
415		}
416	}
