	raw  []byte
	want []string
}{
	// 任务示例：删除资金库侧的 after（本来应为 0）必须拒绝。
	{"treasury after missing (would be 0)", mutateReceipt(0, 0, "treasury", "after", nil),
		[]string{`"gip-1"`, "action 0", "treasury", `"after"`, "missing"}},
	// 任务示例：删除收款账户侧的 before（本来应为 0）必须拒绝。
	{"recipient before missing (would be 0)", mutateReceipt(0, 0, "recipient", "before", nil),
		[]string{`"gip-1"`, "action 0", "recipient", `"before"`, "missing"}},
	// 非零字段缺失适用同一规则。
	{"treasury before missing (non-zero)", mutateReceipt(0, 0, "treasury", "before", nil),
		[]string{`"gip-1"`, "action 0", "treasury", `"before"`, "missing"}},
	{"recipient after missing (non-zero)", mutateReceipt(0, 0, "recipient", "after", nil),
		[]string{`"gip-1"`, "action 0", "recipient", `"after"`, "missing"}},
	// null 与类型不符同样不得折叠成 0。
	{"treasury after null", mutateReceipt(0, 0, "treasury", "after", json.RawMessage("null")),
		[]string{`"gip-1"`, "action 0", "treasury", `"after"`, "null"}},
	{"recipient before wrong type", mutateReceipt(0, 0, "recipient", "before", "0"),
		[]string{`"gip-1"`, "action 0", "recipient", `"before"`, "wrong type"}},
	// 投票通过提案的凭据适用同一规则。
	{"vote receipt treasury after missing", mutateReceipt(1, 0, "treasury", "after", nil),
		[]string{`"gip-vote"`, "action 0", "treasury", `"after"`, "missing"}},
}

